const src = $('Match Extract Filter').item.json;
let out = { action: 'skip', client_id: src.client_id, client_name: src.client_name, meeting_date: '1900-01-01', docId: src.docId };
try {
  const r = JSON.parse($json.choices[0].message.content);
  if (!r.skip && r.title && /^\d{4}-\d{2}-\d{2}$/.test(r.meeting_date || '') && Array.isArray(r.points) && r.points.length) {
    out = { action: 'insert', client_id: src.client_id, client_name: src.client_name, slug: src.slug, title: String(r.title).slice(0, 120), meeting_date: r.meeting_date, points: r.points.map(p => String(p)), docId: src.docId };
  }
} catch (e) {}
return { json: out };

const parsed = $('Parse Summary').all();
const checks = $input.all();
const out = [];
for (let i = 0; i < checks.length; i++) {
  const p = (parsed[i] || {}).json || {};
  const alreadyExists = !!(checks[i].json && checks[i].json.id);
  if (p.action === 'insert' && !alreadyExists) out.push({ json: p });
}
return out;

const clients = $('Split Into Items').all().map(i => i.json);
const logRows = $('Fetch Automation Log').all().map(i => i.json);
const processedIds = new Set($('Fetch Processed Transcripts').all().map(i => i.json.doc_id).filter(Boolean));
const seen = new Set();
const out = [];
for (const row of logRows) {
  if (row['Status'] !== 'Completed') continue;
  const refId = row['Ref ID'] || '';
  if (!refId.startsWith('gemini_')) continue;
  const docId = refId.slice('gemini_'.length);
  if (!docId || seen.has(docId) || processedIds.has(docId)) continue;
  const title = row['Meeting Title'] || '';
  const norm = s => String(s).toLowerCase().replace(/[^a-z0-9]/g, '');
  const normTitle = norm(title);
  const client = clients.find(c => normTitle.includes(norm(c.name)));
  if (!client) continue;
  seen.add(docId);
  out.push({ json: { docId, docName: title, client_id: client.id, client_name: client.name, slug: client.slug } });
}
return out;

